import generated from "./trino-functions.gen.json"

/**
 * The functions of the Trino version Overcast's query engine runs, for the
 * editor's completion. Generated by `web/scripts/generate-trino-functions.mjs`
 * from the engine image itself; `trino-functions.test.ts` fails when the
 * image moves to another version without the list.
 */
export interface TrinoFunction {
  name: string
  /** `scalar`, `aggregate`, `window` or `table`. */
  kind: string
  /** `date_trunc(varchar(x), date) → date`, one per overload. */
  signatures: string[]
  description: string
}

export const TRINO_FUNCTIONS: { trinoVersion: string; functions: TrinoFunction[] } = generated
